import{_ as e}from"./chunks/buildings.C_3pyMYf.js";import{_ as d,o as l,c as a,a0 as r}from"./chunks/framework.DYAX5gPL.js";const x=JSON.parse('{"title":"矢量瓦片与3DTiles的比较","description":"","frontmatter":{"title":"矢量瓦片与3DTiles的比较"},"headers":[],"relativePath":"api/vt-compare.md","filePath":"api/vt-compare.md"}'),s={name:"api/vt-compare.md"};function i(o,t,p,n,c,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="矢量瓦片与3dtiles的比较" tabindex="-1">矢量瓦片与3DTiles的比较 <a class="header-anchor" href="#矢量瓦片与3dtiles的比较" aria-label="Permalink to &quot;矢量瓦片与3DTiles的比较&quot;">​</a></h1><p><img src="'+e+'" alt="城市白模"></p><p>业内习惯把上图中由二维矢量数据转换成的三维建筑，称为建筑白模。</p><p>矢量瓦片图层与3DTiles均能实现城市大场景建筑白模的三维渲染，它们的主要对比：</p><table tabindex="0"><thead><tr><th style="text-align:left;">功能</th><th>矢量瓦片</th><th>3DTiles</th></tr></thead><tbody><tr><td style="text-align:left;">数据存储方式</td><td>数据库或文件</td><td>静态模型文件</td></tr><tr><td style="text-align:left;">实时数据更新</td><td>✔</td><td>❌</td></tr><tr><td style="text-align:left;">实时更新样式</td><td>✔</td><td>❌</td></tr><tr><td style="text-align:left;">批量模型渲染(I3DM)</td><td>✔</td><td>✔</td></tr><tr><td style="text-align:left;">点云数据</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">倾斜摄影</td><td>❌</td><td>✔</td></tr><tr><td style="text-align:left;">三维生成策略</td><td>前端实时生成</td><td>软件转换</td></tr><tr><td style="text-align:left;">性能</td><td>高</td><td>差</td></tr><tr><td style="text-align:left;">开源生态支持</td><td>丰富</td><td>少量</td></tr></tbody></table><p>因此，对于三维建筑白模渲染，我们认为矢量瓦片是更好的技术方案。</p><p>但对于点云和倾斜摄影数据，3DTiles依然是最好的技术方案，是矢量瓦片无法替代的。</p><blockquote><p>本文档已与 @maptalks/gl-layers 2026 源码核对（api-notes-vt-gl.md）</p></blockquote>',8)])])}const g=d(s,[["render",i]]);export{x as __pageData,g as default};
